// The contract files bundled with the app, generated by scripts/gen-vault-contract.mts and
// carried here as SPM resources — the same bytes packages/core/contract holds, so a Mac-made
// vault and a phone-made vault ship byte-identical contract files. See VaultScaffold.create.
import Foundation

public enum VaultContract {
    /// The generated files a vault carries beside its data, newest bytes this build has.
    public static let files = [
        VaultReader.schemaFile, VaultReader.llmsFile, VaultReader.libraryFile, VaultReader.promptsFile,
    ]

    /// The generated contract files, ready to pass to `VaultScaffold.create(contractFiles:)`.
    /// Empty if the bundle is missing a file — scaffolding degrades gracefully, never crashes.
    public static func bundledFiles() -> [String: Data] {
        var out: [String: Data] = [:]
        for name in files {
            let asURL = URL(fileURLWithPath: name)
            let resource = asURL.deletingPathExtension().lastPathComponent
            guard let url = Bundle.module.url(forResource: resource, withExtension: asURL.pathExtension),
                  let data = try? Data(contentsOf: url)
            else { continue }
            out[name] = data
        }
        return out
    }

    /// The bundled schema, parsed — what a write is checked against.
    ///
    /// Read from this build's copy, never the vault's: the vault's is an artifact this app
    /// wrote, and anything with the folder open can edit it or leave it a version behind.
    public static func bundledSchema() -> [String: Any]? {
        guard let data = bundledFiles()[VaultReader.schemaFile] else { return nil }
        return (try? JSONSerialization.jsonObject(with: data)) as? [String: Any]
    }

    /// The revision stamped into a contract set, read from `library.json`. `prompts.json` carries
    /// the same number; the schema's own `version` is the data format and says so.
    static func revision(of library: Data?) -> Int? {
        guard let library,
              let object = try? JSONSerialization.jsonObject(with: library) as? [String: Any]
        else { return nil }
        return object["contract_revision"] as? Int
    }

    /// Whether a prompts.json is longbook's own: a JSON object carrying a revision stamp. The
    /// name is common enough that a folder someone picked may hold a file of their own.
    static func isOurPrompts(_ data: Data) -> Bool {
        guard let object = (try? JSONSerialization.jsonObject(with: data)) as? [String: Any] else { return false }
        return object["contract_revision"] != nil
    }

    /// The order a set is written in: library.json, which carries the revision stamp, goes last,
    /// so a device that reads the new stamp finds the rest of the set already there.
    static func writeOrder<Names: Sequence>(_ names: Names) -> [String] where Names.Element == String {
        let all = names.sorted()
        return all.filter { $0 != VaultReader.libraryFile } + all.filter { $0 == VaultReader.libraryFile }
    }

    /// Bring a vault's contract files level with this build's; returns what was rewritten.
    ///
    /// Older bytes never replace newer, or two devices on different releases trade writes
    /// forever. An unstamped set loses; a level one gains only missing files. Blocks: call it
    /// off the main actor. Tests swap `write`.
    @discardableResult
    public static func heal(
        in folder: URL,
        bundled: [String: Data] = bundledFiles(),
        fileManager: FileManager = .default,
        write: (Data, URL) throws -> Void = { try VaultScaffold.coordinatedWrite($0, to: $1) }
    ) -> [String] {
        let scoped = folder.startAccessingSecurityScopedResource()
        defer { if scoped { folder.stopAccessingSecurityScopedResource() } }

        // A vault made before documents/ existed gets one here. Independent of the contract
        // revision: a folder can be level and still predate the readers that need it.
        let documents = folder.appendingPathComponent("documents", isDirectory: true)
        if !fileManager.fileExists(atPath: documents.path) {
            try? fileManager.createDirectory(at: documents, withIntermediateDirectories: true)
        }

        guard let mine = revision(of: bundled[VaultReader.libraryFile]) else { return [] }

        let listing = Set((try? fileManager.contentsOfDirectory(atPath: folder.path)) ?? [])
        // A copy iCloud hasn't sent yet lists under a dot-name and holds no bytes here. Asking
        // for it and leaving it alone is the difference between healing and a conflict copy.
        var pending = false
        var onDisk: [String: Data] = [:]
        for name in files {
            if listing.contains(".\(name).icloud") {
                try? fileManager.startDownloadingUbiquitousItem(at: folder.appendingPathComponent(name))
                pending = true
                continue
            }
            guard listing.contains(name) else { continue }
            guard let bytes = try? VaultReader.coordinatedRead(folder.appendingPathComponent(name)) else {
                // Unreadable is not stale. Leave a file we could not open.
                pending = true
                continue
            }
            onDisk[name] = bytes
        }
        if pending { return [] }
        let theirs = revision(of: onDisk[VaultReader.libraryFile])
        if let theirs, theirs > mine { return [] }
        // Same revision, same generator run, same bytes: a missing file is written, a differing
        // one is left as found. Covers a set written before this build listed one of its files.
        let level = theirs == mine

        var rewritten: [String] = []
        var failed = false
        for name in writeOrder(files) {
            guard let wanted = bundled[name], onDisk[name] != wanted else { continue }
            if level, onDisk[name] != nil { continue }
            // A prompts.json longbook did not write is the owner's: left as found, and not written.
            if name == VaultReader.promptsFile, let found = onDisk[name], !isOurPrompts(found) { continue }
            // A stamp over a set that failed to land would read as level and never heal again.
            if name == VaultReader.libraryFile, failed { continue }
            do {
                try write(wanted, folder.appendingPathComponent(name))
                rewritten.append(name)
            } catch {
                // A folder the owner can only read still opens, with the contract it had.
                failed = true
                continue
            }
        }
        return rewritten
    }
}
